{"path":"tools/LetUsCook.AutoWrongCensus/AutoWrongCensusCli.cs","i":"Creating CLI entry point","content":"using LetUsCook.AutoWrongCensus.HostedServices;
using LetUsCook.AutoWrongCensus.Options;

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

namespace LetUsCook.AutoWrongCensus;

/// <summary>
/// The console entry point for the auto-wrong census (F-428 P12.13). <c>Program.cs</c> is a one-line
/// delegation here so the golden test can run the exact same host graph through the same entry
/// without spawning a process.
/// </summary>
public static class AutoWrongCensusCli
{
	/// <summary>Runs the host to completion and returns the exit code (the CLI contract).</summary>
	/// <param name="args">The command line arguments.</param>
	public static async Task<int> RunAsync(string[] args)
	{
		if (Array.Exists(args, a => a.Equals("--help", StringComparison.OrdinalIgnoreCase) || a.Equals("-h", StringComparison.OrdinalIgnoreCase)))
		{
			AutoWrongCensusUsage.Print();
			return 0;
		}

		var builder = AutoWrongCensusHostBuilderFactory.Create(args);
		var host = builder.Build();

		// Resolve BEFORE RunAsync(): RunAsync disposes the provider on shutdown.
		var hostedService = host.Services.GetRequiredService<AutoWrongCensusHostedService>();
		await host.RunAsync().ConfigureAwait(false);
		return hostedService.ExitCode;
	}
}
"}

{"path":"tools/LetUsCook.AutoWrongCensus/AutoWrongCensusCli.cs","i":"Writing CLI entry point","content":"using LetUsCook.AutoWrongCensus.HostedServices;
using LetUsCook.AutoWrongCensus.Options;

using Microsoft.Extensions.DependencyInjection;

namespace LetUsCook.AutoWrongCensus;

/// <summary>
/// The console entry point of the auto-wrong census (F-428 P12.13). Builds the same host graph
/// <c>Program.cs</c> uses and returns the hosted service's exit code, so tests can run the real
/// path with captured writers.
/// </summary>
public static class AutoWrongCensusCli
{
	/// <summary>Runs the CLI. <paramref name="output"/>/<paramref name="error"/> default to the console.</summary>
	public static async Task<int> RunAsync(
		string[] args,
		TextWriter? output = null,
		TextWriter? error = null,
		CancellationToken cancellationToken = default)
	{
		ArgumentNullException.ThrowIfNull(args);

		if (Array.Exists(args, a => a.Equals("--help", StringComparison.OrdinalIgnoreCase) || a.Equals("-h", StringComparison.OrdinalIgnoreCase)))
		{
			AutoWrongCensusUsage.Print();
			return 0;
		}

		var builder = AutoWrongCensusHostBuilderFactory.Create(args, output, error);
		var host = builder.Build();

		var hostedService = host.Services.GetRequiredService<AutoWrongCensusHostedService>();
		await host.RunAsync(cancellationToken).ConfigureAwait(false);
		return hostedService.ExitCode;
	}
}
"}

