{"path":"tools/LetUsCook.AutoWrongCensus/Options/CommandLineArgumentParser.cs","i":"Writing argument parser","content":"namespace LetUsCook.AutoWrongCensus.Options;

/// <summary>
/// Parses the census CLI's positional subcommands into configuration keys:
/// <c>census &lt;trace.jsonl&gt;</c> and <c>pairs &lt;census-tsv&gt; &lt;trace.jsonl&gt;</c>.
/// Anything else yields an empty dictionary, which the runner answers with usage and exit 1.
/// </summary>
public static class CommandLineArgumentParser
{
	public static Dictionary<string, string?> Parse(string[] args)
	{
		ArgumentNullException.ThrowIfNull(args);
		var dict = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);

		if (args.Length < 1)
		{
			return dict;
		}

		var command = args[0].ToLowerInvariant();
		if (command is "census" or "pairs")
		{
			dict[AutoWrongCensusOptions.SectionName + ":Command"] = command;
		}

		if (command == "census" && args.Length >= 2)
		{
			dict[AutoWrongCensusOptions.SectionName + ":TracePath"] = args[1];
		}
		else if (command == "pairs" && args.Length >= 3)
		{
			dict[AutoWrongCensusOptions.SectionName + ":CensusTsvPath"] = args[1];
			dict[AutoWrongCensusOptions.SectionName + ":TracePath"] = args[2];
		}

		return dict;
	}
}
"}

