{"path":"tools/LetUsCook.AutoWrongCensus/Options/CommandLineArgumentParser.cs","i":"Writing argument parser","content":"namespace LetUsCook.AutoWrongCensus.Options;

/// <summary>
/// Positional CLI syntax for the census: <c>census &lt;trace.jsonl&gt;</c> and
/// <c>pairs &lt;census.tsv&gt; &lt;trace.jsonl&gt;</c>. Anything else parses to an empty
/// dictionary and the runner answers with the usage and a non-zero exit.
/// </summary>
public static class CommandLineArgumentParser
{
	/// <summary>Parses the positional subcommand and its paths into configuration keys.</summary>
	/// <param name="args">Raw CLI arguments.</param>
	/// <returns>Configuration keys under <see cref="AutoWrongCensusOptions.SectionName"/>; empty when the invocation is unusable.</returns>
	public static Dictionary<string, string?> Parse(string[] args)
	{
		ArgumentNullException.ThrowIfNull(args);
		var dict = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);

		if (args.Length == 2
			&& args[0].Equals("census", StringComparison.OrdinalIgnoreCase)
			&& args[1].Length > 0)
		{
			dict[Key("Command")] = "census";
			dict[Key("TracePath")] = args[1];
		}
		else if (args.Length == 3
			&& args[0].Equals("pairs", StringComparison.OrdinalIgnoreCase)
			&& args[1].Length > 0
			&& args[2].Length > 0)
		{
			dict[Key("Command")] = "pairs";
			dict[Key("CensusTsvPath")] = args[1];
			dict[Key("TracePath")] = args[2];
		}

		return dict;
	}

	private static string Key(string name) => $"{AutoWrongCensusOptions.SectionName}:{name}";
}
"}

