{"path":"tools/LetUsCook.AutoWrongCensus/Models/TraceLine.cs","i":"Writing trace record DTO","content":"using System.Text.Json.Serialization;

namespace LetUsCook.AutoWrongCensus.Models;

/// <summary>
/// One HoldoutGate trace line, as written by <c>HoldoutGateRunner</c> (camelCase JSONL). Only the fields
/// the census reads are modelled; unknown fields are ignored on deserialization.
/// </summary>
public sealed record TraceLine
{
	/// <summary>The raw recipe line text.</summary>
	[JsonPropertyName("rawText")]
	public string RawText { get; init; } = string.Empty;

	/// <summary>Holdout line id, e.g. <c>debug:alisons-slow-cooker-vegetable-beef-s</c>.</summary>
	[JsonPropertyName("holdoutId")]
	public string HoldoutId { get; init; } = string.Empty;

	/// <summary>Line index within the recipe.</summary>
	[JsonPropertyName("lineIndex")]
	public int LineIndex { get; init; }

	/// <summary>Trace set: <c>debug</c> or <c>batch</c>; anything else is refused (D-029).</summary>
	[JsonPropertyName("set")]
	public string Set { get; init; } = string.Empty;

	/// <summary>Whether the line shipped to the household without review.</summary>
	[JsonPropertyName("auto")]
	public bool Auto { get; init; }

	/// <summary>Whether the shipped row is the labelled (key) row.</summary>
	[JsonPropertyName("correct")]
	public bool Correct { get; init; }

	/// <summary>Labelled (key) row descriptions; empty for an unlabelled line.</summary>
	[JsonPropertyName("expectedDescriptions")]
	public IReadOnlyList<string> ExpectedDescriptions { get; init; } = [];

	/// <summary>Labelled (key) row dataset tiers.</summary>
	[JsonPropertyName("expectedDataTypes")]
	public IReadOnlyList<string> ExpectedDataTypes { get; init; } = [];

	/// <summary>Shipped (accepted) row descriptions.</summary>
	[JsonPropertyName("actualDescriptions")]
	public IReadOnlyList<string> ActualDescriptions { get; init; } = [];

	/// <summary>Shipped (accepted) row dataset tiers.</summary>
	[JsonPropertyName("actualDataTypes")]
	public IReadOnlyList<string> ActualDataTypes { get; init; } = [];

	/// <summary>Per-atom pipeline decisions.</summary>
	[JsonPropertyName("atoms")]
	public IReadOnlyList<TraceAtom> Atoms { get; init; } = [];
}

/// <summary>One atom (sub-line) decision inside a trace line.</summary>
public sealed record TraceAtom
{
	/// <summary>Decision path: <c>ranker</c>, <c>override</c>, or <c>curated</c>.</summary>
	[JsonPropertyName("path")]
	public string Path { get; init; } = string.Empty;

	/// <summary>Whether the atom reused an existing ingredient master row.</summary>
	[JsonPropertyName("reused")]
	public bool Reused { get; init; }

	/// <summary>The parsed ingredient name the atom resolved from.</summary>
	[JsonPropertyName("parsedName")]
	public string ParsedName { get; init; } = string.Empty;

	/// <summary>The linked ingredient master slug, when one was minted or reused.</summary>
	[JsonPropertyName("linkedIngredientId")]
	public string? LinkedIngredientId { get; init; }

	/// <summary>Atom outcome: <c>accepted</c>, <c>deferred</c>, or <c>rejected</c>.</summary>
	[JsonPropertyName("outcome")]
	public string Outcome { get; init; } = string.Empty;
}
"}

{"path":"tools/LetUsCook.AutoWrongCensus/Models/CensusRow.cs","i":"Writing census output row","content":"namespace LetUsCook.AutoWrongCensus.Models;

/// <summary>
/// One classified auto-wrong line. The TSV column order is the public contract of the <c>census</c>
/// subcommand (brief §4); <see cref="TierDirection"/> and <see cref="QualifierDiff"/> are stderr-only
/// detail for the <c>row-choice-tier</c> and <c>same-head-other-qualifier</c> relations.
/// </summary>
public sealed record CensusRow
{
	/// <summary>Holdout line id.</summary>
	public string HoldoutId { get; init; } = string.Empty;

	/// <summary>Line index within the recipe.</summary>
	public int LineIndex { get; init; }

	/// <summary>Trace set (<c>debug</c> or <c>batch</c>).</summary>
	public string Set { get; init; } = string.Empty;

	/// <summary>Relation class: the accepted row vs the key row (brief §4, first match wins).</summary>
	public string Relation { get; init; } = string.Empty;

	/// <summary>Decision site: <c>reuse</c>, <c>ranker</c>, <c>override</c>, or <c>curated</c>.</summary>
	public string Site { get; init; } = string.Empty;

	/// <summary>For <c>override</c> sites: <c>yes</c>/<c>no</c> — whether the normalised raw text is a key of exact-overrides.json.</summary>
	public string OverrideKey { get; init; } = string.Empty;

	/// <summary>Accepted row dataset tier.</summary>
	public string AcceptedTier { get; init; } = string.Empty;

	/// <summary>Key row dataset tier.</summary>
	public string KeyTier { get; init; } = string.Empty;

	/// <summary>Accepted row <c>FoodState</c> mask (state words plus satisfiers, production extraction).</summary>
	public string AcceptedState { get; init; } = string.Empty;

	/// <summary>Key row <c>FoodState</c> mask (state words plus satisfiers, production extraction).</summary>
	public string KeyState { get; init; } = string.Empty;

	/// <summary>The atom's parsed name, verbatim.</summary>
	public string ParsedName { get; init; } = string.Empty;

	/// <summary>The key row's head phrase (head term plus non-state qualifier words), singularised.</summary>
	public string KeyHead { get; init; } = string.Empty;

	/// <summary>Accepted row description, verbatim.</summary>
	public string AcceptedDesc { get; init; } = string.Empty;

	/// <summary>Key row description, verbatim.</summary>
	public string KeyDesc { get; init; } = string.Empty;

	/// <summary>The raw recipe line text.</summary>
	public string RawText { get; init; } = string.Empty;

	/// <summary>For <c>row-choice-tier</c>: which tier is higher — <c>key</c>, <c>accepted</c>, or empty.</summary>
	public string TierDirection { get; init; } = string.Empty;

	/// <summary>For <c>same-head-other-qualifier</c>: the qualifier words that differ, or empty.</summary>
	public string QualifierDiff { get; init; } = string.Empty;

	/// <summary>Set when a field the relation ladder needs is missing from the trace (brief §8).</summary>
	public string MissingField { get; init; } = string.Empty;
}
"}

{"i":"Writing override key index","path":"tools/LetUsCook.AutoWrongCensus/Services/ExactOverrideKeyIndex.cs","content":"using System.Collections.Frozen;
using System.Text.Json;

using LetUsCook.Fdc.Lexicon;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Key set of the production <c>exact-overrides.json</c> (embedded in the Fdc assembly), used by the
/// <c>override</c>-site lines to answer "is the normalized rawText an override key?". The file is the
/// data; the normalization that is applied before the lookup is the production one
/// (cut at the first parenthesis, trim, lowercase — <c>FdcMatcher.MatchAsync</c>'s raw-key lookup).
/// </summary>
public sealed class ExactOverrideKeyIndex
{
	private readonly FrozenSet<string> _keys;

	/// <summary>Loads the embedded <c>exact-overrides.json</c> key set.</summary>
	public ExactOverrideKeyIndex()
	{
		var assembly = typeof(FdcNormalizer).Assembly;
		var name = assembly.GetManifestResourceNames().Single(n => n.EndsWith("exact-overrides.json", StringComparison.Ordinal));
		using var stream = assembly.GetManifestResourceStream(name)
			?? throw new InvalidOperationException($"Embedded resource '{name}' not found.");
		using var reader = new StreamReader(stream);
		using var doc = JsonDocument.Parse(reader.ReadToEnd());
		_keys = doc.RootElement.EnumerateObject().Select(p => p.Name).ToFrozenSet(StringComparer.OrdinalIgnoreCase);
	}

	/// <summary>Gets the number of keys loaded.</summary>
	public int Count => _keys.Count;

	/// <summary>Returns whether the (already normalized) key is an <c>exact-overrides.json</c> key.</summary>
	/// <param name="key">The normalized raw text.</param>
	public bool Contains(string key) => _keys.Contains(key);
}
"}

{"path":"tools/LetUsCook.AutoWrongCensus/Services/AutoWrongClassifier.cs","i":"Writing the classifier","content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes — the accepted row's relation to the key row,
/// and the decision site — using the production helpers (F-428 P12.13, D-014: no re-implementation
/// of matcher logic).
/// <para>
/// Relation (first that holds wins, brief §4):
/// <list type="number">
/// <item><c>no-label</c> — no expected row.</item>
/// <item><c>pack-unit-state</c> — rawText carries a can/jar unit, the key's state mask has <see cref="FoodState.Canned"/>, the accepted row's does not.</item>
/// <item><c>compound-head-lost</c> — the key head phrase has two or more words and the singularised parsedName is exactly its first word.</item>
/// <item><c>state-mismatch</c> — head terms agree after singularising and the state masks differ.</item>
/// <item><c>row-choice-tier</c> — head terms and state agree and the dataset tier differs.</item>
/// <item><c>same-head-other-qualifier</c> — head terms agree and nothing above holds.</item>
/// <item><c>sibling-food</c> — head terms differ.</item>
/// <item><c>other</c> — a relation check needed a trace field that is missing.</item>
/// </list>
/// </para>
/// The state mask of a row is the production composition <c>ExtractCandidateState ∪ ExtractCandidateSatisfiers</c>
/// over <c>FdcNormalizer.NormalizeToTokens</c> output (the same pair <c>FdcMatcher.MatchAsync</c> feeds to
/// <c>StateAgrees</c>). The key head phrase is the key's normalized tokens up to the first token the
/// production state/modifier vocabulary flags (<c>ModifierWords</c>, or a non-<c>None</c> single-token
/// <c>ExtractCandidateState</c>/<c>ExtractCandidateSatisfiers</c> result); the parser's own <c>HeadTerm</c>
/// is a single token, so a head phrase is the only production-grounded reading of the brief's
/// "the key's HeadTerm has two or more words" that fires on the §2 bread-crumbs example.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Single-token scratch for the state vocabulary checks; the classifier is used by one thread (the runner).
	private readonly string?[] _singleTokenScratch = new string[1];

	/// <summary>Creates a classifier over the production normalizer and the shipped override key set.</summary>
	/// <param name="normalizer">Production <see cref="FdcNormalizer"/>.</param>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> raw-key set.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>Classifies one auto-wrong line.</summary>
	/// <param name="line">A trace line with <c>auto == true</c> and <c>correct == false</c>.</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();
		var site = ClassifySite(atom?.Path, atom?.Reused);
		var keyDesc = line.ExpectedDescriptions.FirstOrDefault() ?? string.Empty;
		var acceptedDesc = line.ActualDescriptions.FirstOrDefault() ?? string.Empty;
		var keyTier = line.ExpectedDataTypes.FirstOrDefault() ?? string.Empty;
		var acceptedTier = line.ActualDataTypes.FirstOrDefault() ?? string.Empty;

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);
		var headKey = SingularPhrase(keyDesc, keyTier, out var keyQualifiers);
		var headAccepted = SingularPhrase(acceptedDesc, acceptedTier, out var acceptedQualifiers);
		var parsedNameTokens = SingularPhraseTokens(atom?.ParsedName ?? string.Empty);

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Site = site,
			OverrideKey = site == "override" ? (_overrideKeys.IsKey(FoldForOverrideLookup(line.RawText)) ? "yes" : "no") : string.Empty,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
		};

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			result.Relation = "no-label";
			return result;
		}

		if (PackUnitRegex().IsMatch(line.RawText) && (keyState & FoodState.Canned) != 0 && (acceptedState & FoodState.Canned) == 0)
		{
			result.Relation = "pack-unit-state";
			return result;
		}

		if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			result.Relation = "compound-head-lost";
			return result;
		}

		var headsAgree = headKey.SequenceEqual(headAccepted, StringComparer.OrdinalIgnoreCase);
		if (!headsAgree)
		{
			result.Relation = "sibling-food";
			return result;
		}

		if (keyState != acceptedState)
		{
			result.Relation = "state-mismatch";
			return result;
		}

		if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
		{
			result.Relation = "other";
			result.MissingField = string.IsNullOrWhiteSpace(keyTier) ? "expectedDataTypes" : "actualDataTypes";
			return result;
		}

		if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
		{
			result.Relation = "row-choice-tier";
			return result;
		}

		result.Relation = "same-head-other-qualifier";
		result.KeyOnlyQualifiers = QualifierDiff(keyQualifiers, acceptedQualifiers);
		result.AcceptedOnlyQualifiers = QualifierDiff(acceptedQualifiers, keyQualifiers);
		return result;
	}

	/// <summary>
	/// The key head phrase: the key's normalized tokens up to the first token the production
	/// state/modifier vocabulary flags. Deterministic per key description (the tomorrow test).
	/// </summary>
	/// <param name="keyTokens">Normalized tokens of the key description.</param>
	/// <returns>The head phrase tokens (possibly empty).</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		var phrase = new List<string>();
		foreach (var token in keyTokens)
		{
			if (CarriesStateToken(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>
	/// The production state composition for a token list: <c>ExtractCandidateState</c> union
	/// <c>ExtractCandidateSatisfiers</c> — the same pair the matcher feeds to <c>StateAgrees</c>.
	/// </summary>
	/// <param name="tokens">Normalized tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// Folds a raw line text the way the matcher folds it for the raw override lookup:
	/// lower-cased, trimmed, content from the first <c>(</c> dropped (the matcher's
	/// <c>StripFromParenthesis</c> is private; this is that cut, verified against it).
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded text.</returns>
	public static string FoldForOverrideLookup(string rawText)
	{
		var text = rawText.Trim();
		var paren = text.IndexOf('(', StringComparison.Ordinal);
		if (paren >= 0)
		{
			text = text[..paren].Trim();
		}

#pragma warning disable CA1308 // Reason: parity with the matcher's ToLowerInvariant override lookup.
		return text.ToLowerInvariant();
#pragma warning restore CA1308
	}

	/// <summary>
	/// The decision site for one atom: <c>reuse</c> (ranker + reused), <c>ranker</c> (ranker, not reused),
	/// <c>override</c>, or <c>curated</c>; empty for an unknown path.
	/// </summary>
	/// <param name="path">The atom's decision path.</param>
	/// <param name="reused">Whether the atom reused an existing row.</param>
	/// <returns>The site, or empty.</returns>
	public static string ClassifySite(string? path, bool reused) => path switch
	{
		"ranker" => reused ? "reuse" : "ranker",
		"override" => "override",
		"curated" => "curated",
		_ => string.Empty,
	};

	private static IReadOnlyList<string> QualifierDiff(IReadOnlyList<string> a, IReadOnlyList<string> b)
	{
		var aSet = a.ToHashSet(StringComparer.OrdinalIgnoreCase);
		var bSet = b.ToHashSet(StringComparer.OrdinalIgnoreCase);
		return a.Where(t => !bSet.Contains(t)).OrderBy(t => t, StringComparer.OrdinalIgnoreCase).ToArray();
	}

	private bool CarriesStateToken(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleTokenScratch[0] = token;
		return FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch) != FoodState.None;
	}

	private IReadOnlyList<string> SingularPhrase(string description, string tier, out IReadOnlyList<string> qualifiers)
	{
		var parsed = FdcDescriptionParser.Parse(description, DatasetOf(tier));
		qualifiers = parsed.Qualifiers.Select(IngredientLineResolver.SingularizeToken).ToArray();
		return SingularPhraseTokens(parsed.HeadTerm);
	}

	private IReadOnlyList<string> SingularPhraseTokens(string text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();
}
"}

{"path":"tools/LetUsCook.AutoWrongCensus/Services/AutoWrongClassifier.cs","i":"Rewriting classifier cleanly","content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes: the accepted row vs the key row
/// (<see cref="ClassificationResult.Relation"/>) and the decision site
/// (<see cref="ClassificationResult.Site"/>). Every relation test calls production helpers —
/// <see cref="FdcNormalizer.NormalizeToTokens"/>, <see cref="FdcMatcher.ExtractCandidateState"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>, <see cref="FdcDescriptionParser.Parse"/>,
/// <see cref="IngredientLineResolver.SingularizeToken"/> — never a copy of matcher logic (D-014).
/// Not thread-safe: one <c>Classify</c> call at a time.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Raw-text can/jar unit token — the pack-unit shape in P12.13 brief §2.</summary>
	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	private readonly FdcNormalizer _normalizer;

	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused single-token list for the per-token state checks; ExtractCandidateState/Satisfiers only
	// read the list, so re-filling one cell per token is safe on this single-threaded runner and
	// keeps the census allocation-free (CA1861 forbids the constant-array argument form anyway).
	private readonly string[] _singleToken = new string[1];

	/// <summary>Creates the classifier over the production normalizer and the shipped override keys.</summary>
	/// <param name="normalizer">The production <see cref="FdcNormalizer"/>.</param>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> key index.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(overrideKeys);
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	/// <summary>Classifies one trace line. Only <c>auto &amp;&amp; !correct</c> lines are meant for this call.</summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The relation, site and the recorded row facts.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = ChooseAtom(line);
		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);
		var parsedNameTokens = SingularTokens(_normalizer.NormalizeToTokens(atom.ParsedName));

		var (relation, missingField, keyOnlyQualifiers, acceptedOnlyQualifiers) = ClassifyRelation(
			line, keyDesc, acceptedDesc, keyTier, acceptedTier,
			keyState, acceptedState, parsedNameTokens, keyHeadPhrase);

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = SiteOf(atom),
			OverrideKey = SiteOf(atom) == SiteOverride ? (_overrideKeys.IsKey(FoldForOverrideKey(line.RawText)) ? "yes" : "no") : string.Empty,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom.ParsedName,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers,
		};
	}

	/// <summary>Site: the ranker matched and the line reused an existing row.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the ranker picked a fresh row (not reused).</summary>
	public const string SiteRanker = "ranker";

	/// <summary>Site: an override file resolved the line.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue resolved the line.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Relation: the key label is empty.</summary>
	public const string RelationNoLabel = "no-label";

	/// <summary>Relation: the line names a pack unit, the key wants a canned row, the accepted row is not canned.</summary>
	public const string RelationPackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase is multi-word and the parser name kept only its first word.</summary>
	public const string RelationCompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: heads agree, state masks differ.</summary>
	public const string RelationStateMismatch = "state-mismatch";

	/// <summary>Relation: heads and state agree, dataset tiers differ.</summary>
	public const string RelationRowChoiceTier = "row-choice-tier";

	/// <summary>Relation: heads, state and tier agree; qualifier tokens differ.</summary>
	public const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: head terms differ.</summary>
	public const string RelationSiblingFood = "sibling-food";

	/// <summary>Relation: nothing above holds (typically a missing trace field).</summary>
	public const string RelationOther = "other";

	/// <summary>
	/// The key's food-name head phrase: the description's normalized tokens up to the first token that
	/// production itself treats as state or preparation (<see cref="FdcLexicon.ModifierWords"/>,
	/// <see cref="FdcMatcher.ExtractCandidateState"/> or <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>
	/// of that single token). This is the multi-word head the brief's relation 3 asks about —
	/// <c>"Bread, crumbs, dry, grated, plain"</c> → <c>bread crumbs</c>, because <c>dry</c> is the first
	/// production state token — while <c>"Tomatoes, crushed, canned"</c> stays single-word
	/// (<c>crushed</c> is a production modifier). The single-token
	/// <see cref="FdcDescriptionParser.Parse"/> <c>HeadTerm</c> cannot express the former.
	/// </summary>
	/// <param name="normalizedKeyTokens">The key description's normalized tokens.</param>
	/// <returns>The head phrase tokens, lower-cased and singularised.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> normalizedKeyTokens)
	{
		ArgumentNullException.ThrowIfNull(normalizedKeyTokens);

		var phrase = new List<string>(normalizedKeyTokens.Count);
		foreach (var token in normalizedKeyTokens)
		{
			if (CarriesStateToken(token))
			{
				break;
			}

			phrase.Add(IngredientLineResolver.SingularizeToken(token));
		}

		return phrase;
	}

	/// <summary>
	/// The accepted-row vs key-row relation, first class that holds wins (brief §4 order 1–8).
	/// </summary>
	private (string Relation, string? MissingField, IReadOnlyList<string>? KeyOnly, IReadOnlyList<string>? AcceptedOnly) ClassifyRelation(
		TraceLine line,
		string keyDesc,
		string acceptedDesc,
		string keyTier,
		string acceptedTier,
		FoodState keyState,
		FoodState acceptedState,
		IReadOnlyList<string> parsedNameTokens,
		IReadOnlyList<string> keyHeadPhrase)
	{
		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return (RelationNoLabel, null, null, null);
		}

		if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			return (RelationPackUnitState, null, null, null);
		}

		if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], keyHeadPhrase[0], StringComparison.OrdinalIgnoreCase))
		{
			return (RelationCompoundHeadLost, null, null, null);
		}

		var headKey = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).HeadTerm;
		var headAccepted = string.IsNullOrWhiteSpace(acceptedDesc)
			? string.Empty
			: FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).HeadTerm;
		if (!HeadsAgree(headKey, headAccepted))
		{
			return (RelationSiblingFood, null, null, null);
		}

		if (keyState != acceptedState)
		{
			return (RelationStateMismatch, null, null, null);
		}

		if (string.IsNullOrEmpty(acceptedTier) || string.IsNullOrEmpty(keyTier))
		{
			return (RelationOther, string.IsNullOrEmpty(acceptedTier) ? "actualDataTypes" : "expectedDataTypes", null, null);
		}

		if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
		{
			return (RelationRowChoiceTier, null, null, null);
		}

		var keyQualifiers = QualifierSet(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).Qualifiers);
		var acceptedQualifiers = QualifierSet(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).Qualifiers);
		return (RelationSameHeadOtherQualifier, null, keyQualifiers.Except(acceptedQualifiers).ToArray(), acceptedQualifiers.Except(keyQualifiers).ToArray());
	}

	private static TraceAtom ChooseAtom(TraceLine line)
	{
		if (line.Atoms.Count == 0)
		{
			throw new InvalidOperationException($"Trace line {line.HoldoutId}#{line.LineIndex} has no atoms; cannot determine the decision site.");
		}

		foreach (var atom in line.Atoms)
		{
			if (atom.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			{
				return atom;
			}
		}

		return line.Atoms[0];
	}

	private static string SiteOf(TraceAtom atom)
	{
		if (string.Equals(atom.Path, "override", StringComparison.OrdinalIgnoreCase))
		{
			return SiteOverride;
		}

		if (string.Equals(atom.Path, "curated", StringComparison.OrdinalIgnoreCase))
		{
			return SiteCurated;
		}

		if (string.Equals(atom.Path, "ranker", StringComparison.OrdinalIgnoreCase))
		{
			return atom.Reused ? SiteReuse : SiteRanker;
		}

		return string.Empty;
	}

	// Production's override lookup folds the raw text with StripFromParenthesis (private in
	// FdcMatcher): content from the first '(' onward, lower-cased, trimmed. That one-step fold is
	// applied here against the shipped exact-overrides.json keys (brief §4; named in the report).
	private static string FoldForOverrideKey(string rawText)
	{
		var cut = rawText.IndexOf('(', StringComparison.Ordinal);
#pragma warning disable CA1308 // Reason: parity with FdcMatcher's override-lookup fold (lower-cased key).
		return (cut >= 0 ? rawText[..cut] : rawText).Trim().ToLowerInvariant();
#pragma warning restore CA1308
	}

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private bool HeadsAgree(string headKey, string headAccepted)
	{
		var keyTokens = SingularTokens(_normalizer.NormalizeToTokens(headKey));
		var acceptedTokens = SingularTokens(_normalizer.NormalizeToTokens(headAccepted));
		return keyTokens.SequenceEqual(acceptedTokens, StringComparer.OrdinalIgnoreCase);
	}

	private static HashSet<string> QualifierSet(IReadOnlyList<string> qualifiers) =>
		new(qualifiers.Select(t => IngredientLineResolver.SingularizeToken(t)), StringComparer.OrdinalIgnoreCase);

	private FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	private bool CarriesStateToken(string token)
	{
		_singleToken[0] = token;
		return FdcLexicon.Default.ModifierWords.Contains(token)
			|| FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static IReadOnlyList<string> SingularTokens(IReadOnlyList<string> tokens) =>
		Array.ConvertAll(tokens.ToArray(), t => IngredientLineResolver.SingularizeToken(t));
}
"}

