/// <summary>Executes one census or pairs invocation.</summary>
public interface IAutoWrongCensusRunner
{
	/// <summary>Runs the invocation bound in the options.</summary>
	/// <param name="cancellationToken">Cancellation token.</param>
	/// <returns>0 on success; 1 on a missing file, a refused set, or a malformed input.</returns>
	Task<int> RunAsync(CancellationToken cancellationToken);
