{"path":"tools/LetUsCook.AutoWrongCensus/Services/AutoWrongCensusRunner.cs","i":"Writing census runner","content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The census engine: reads one HoldoutGate trace JSONL, refuses any set other than
/// <c>debug</c>/<c>batch</c> (D-029), classifies every <c>auto &amp;&amp; !correct</c> line, and writes
/// the TSV (stdout sink) plus the relation × site summary (stderr sink). The <c>pairs</c> subcommand
/// joins P12.7 blocker rows (<c>blocker=window</c>, <c>route</c> compound/other) with the trace.
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	FdcNormalizer normalizer,
	OutputWriters writers) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private static readonly string[] TsvColumns =
	[
		"holdoutId", "lineIndex", "set", "relation", "site", "overrideKey",
		"acceptedTier", "keyTier", "acceptedState", "keyState",
		"parsedName", "keyHead", "acceptedDesc", "keyDesc", "rawText",
	];

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		var opts = options.Value;
		if (opts.Command == CommandLineArgumentParser.CensusCommand)
		{
			return await RunCensusAsync(opts.TracePath, cancellationToken).ConfigureAwait(false);
		}

		if (opts.Command == CommandLineArgumentParser.PairsCommand)
		{
			return await RunPairsAsync(opts.CensusTsvPath, opts.TracePath, cancellationToken).ConfigureAwait(false);
		}

		writers.Error.WriteLine("unusable arguments; expected: census <trace.jsonl> | pairs <census.tsv> <trace.jsonl>");
		Options.AutoWrongCensusUsage.Print();
		return 1;
	}

	private async Task<int> RunCensusAsync(string tracePath, CancellationToken cancellationToken)
	{
		if (!File.Exists(tracePath))
		{
			writers.Error.WriteLine($"trace not found: {tracePath}");
			return 1;
		}

		var lines = await ReadTraceAsync(tracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.FirstOrDefault(l => !IsAllowedSet(l.Set));
		if (refused is not null)
		{
			writers.Error.WriteLine($"refused: set '{refused.Set}' is not debug or batch (D-029)");
			return 1;
		}

		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();

		writers.Output.WriteLine(string.Join('\t', TsvColumns));
		foreach (var line in autoWrong)
		{
			cancellationToken.ThrowIfCancellationRequested();

			var result = classifier.Classify(line);
			if (result.Site.Length == 0)
			{
				writers.Error.WriteLine($"unknown atom path '{line.Atoms[0].Path}' for {line.HoldoutId}#{line.LineIndex}; refusing to guess a site");
				return 1;
			}

			writers.Output.WriteLine(string.Join('\t',
				result.HoldoutId,
				result.LineIndex.ToString(),
				result.Set,
				result.Relation,
				result.Site,
				result.OverrideKey,
				result.AcceptedTier,
				result.KeyTier,
				result.AcceptedState,
				result.KeyState,
				Clean(result.ParsedName),
				Clean(result.KeyHead),
				Clean(result.AcceptedDesc),
				Clean(result.KeyDesc),
				Clean(result.RawText)));
		}

		WriteSummary(lines.Count, autoWrong);
		return 0;
	}

	private async Task<int> RunPairsAsync(string censusTsvPath, string tracePath, CancellationToken cancellationToken)
	{
		if (!File.Exists(censusTsvPath))
		{
			writers.Error.WriteLine($"census tsv not found: {censusTsvPath}");
			return 1;
		}

		if (!File.Exists(tracePath))
		{
			writers.Error.WriteLine($"trace not found: {tracePath}");
			return 1;
		}

		var lines = await ReadTraceAsync(tracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.FirstOrDefault(l => !IsAllowedSet(l.Set));
		if (refused is not null)
		{
			writers.Error.WriteLine($"refused: set '{refused.Set}' is not debug or batch (D-029)");
			return 1;
		}

		var wanted = ReadWindowRows(censusTsvPath);
		if (wanted is null)
		{
			return 1;
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		var emitted = 0;
		var unmatched = 0;

		writers.Output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");
		foreach (var (holdoutId, lineIndex) in wanted)
		{
			cancellationToken.ThrowIfCancellationRequested();

			if (!byKey.TryGetValue((holdoutId, lineIndex), out var line))
			{
				unmatched++;
				continue;
			}

			var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(normalizer.NormalizeToTokens(keyDesc)));
			writers.Output.WriteLine(string.Join('\t',
				line.HoldoutId,
				line.LineIndex.ToString(),
				Clean(FoldName(line.Atoms.Count > 0 ? line.Atoms[0].ParsedName : string.Empty)),
				Clean(keyHead),
				Clean(line.RawText)));
			emitted++;
		}

		writers.Error.WriteLine($"pairs: window compound/other rows={wanted.Count} emitted={emitted} unmatched={unmatched}");
		return 0;
	}

	private void WriteSummary(int traced, IReadOnlyList<TraceLine> autoWrong)
	{
		var results = autoWrong.Select(l => classifier.Classify(l)).ToList();
		writers.Error.WriteLine($"autoWrongCensus traced={traced} autoWrong={results.Count}");

		foreach (var group in results.GroupBy(r => (r.Relation, r.Site)).OrderBy(g => g.Key.Relation).ThenBy(g => g.Key.Site))
		{
			writers.Error.WriteLine($"{group.Key.Relation}\t{group.Key.Site}\t{group.Count()}");
		}

		var other = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		writers.Error.WriteLine($"other={other}/{results.Count} ({(results.Count == 0 ? 0.0 : other * 100.0 / results.Count):F1}%)");

		var missing = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField!.Value).OrderBy(g => g.Key);
		if (missing.Any())
		{
			writers.Error.WriteLine("missingFields: " + string.Join(", ", missing.Select(g => $"{g.Key}={g.Count()}")));
		}

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		if (overrideLines.Count > 0)
		{
			writers.Error.WriteLine($"overrideKey yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")}");
		}

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		if (reuseLines.Count > 0)
		{
			var checkedCount = 0;
			var notReuse = 0;
			foreach (var line in autoWrong.Where(l => l.Auto && !l.Correct))
			{
				var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line.Atoms[0];
				if (atom.Path.ToLowerInvariant() != "ranker" || !atom.Reused || string.IsNullOrEmpty(atom.LinkedIngredientId))
				{
					continue;
				}

				checkedCount++;
				if (!IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(atom.ParsedName), atom.LinkedIngredientId))
				{
					notReuse++;
				}
			}

			writers.Error.WriteLine($"reuse lines={reuseLines.Count} shouldReuse(parsedName, linkedIngredientId) false={notReuse}/{checkedCount}");
		}

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		if (tierLines.Count > 0)
		{
			writers.Error.WriteLine($"row-choice-tier key higher={tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier))} accepted higher={tierLines.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier))}");
		}

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			writers.Error.WriteLine($"qualdiff {r.HoldoutId}#{r.LineIndex} keyOnly=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	// Foundation > SrLegacy > Survey > Branded (brief §4).
	private static int TierRank(string tier) => tier switch
	{
		"Foundation" => 4,
		"SrLegacy" => 3,
		"Survey" => 2,
		"Branded" => 1,
		_ => 0,
	};

	private async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string tracePath, CancellationToken cancellationToken)
	{
		var lines = new List<TraceLine>();
		await foreach (var raw in File.ReadLinesAsync(tracePath).ConfigureAwait(false).WithCancellation(cancellationToken))
		{
			if (string.IsNullOrWhiteSpace(raw))
			{
				continue;
			}

			try
			{
				lines.Add(JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions)
					?? throw new InvalidOperationException("trace line deserialized to null"));
			}
			catch (JsonException ex)
			{
				writers.Error.WriteLine($"trace parse error in {tracePath}: {ex.Message}");
				return null;
			}
		}

		return lines;
	}

	private static HashSet<(string HoldoutId, int LineIndex)>? ReadWindowRows(string censusTsvPath)
	{
		var rows = File.ReadLines(censusTsvPath).ToList();
		if (rows.Count == 0)
		{
			return null;
		}

		var header = rows[0].Split('\t');
		var indexOf = new Dictionary<string, int>(StringComparer.Ordinal);
		for (var i = 0; i < header.Length; i++)
		{
			indexOf[header[i]] = i;
		}

		foreach (var column in new[] { "holdoutId", "lineIndex", "blocker", "route" })
		{
			if (!indexOf.ContainsKey(column))
			{
				Console.Error.WriteLine($"census tsv missing column '{column}': {censusTsvPath}");
				return null;
			}
		}

		var wanted = new HashSet<(string, int)>();
		for (var i = 1; i < rows.Count; i++)
		{
			var cells = rows[i].Split('\t');
			if (cells.Length < header.Length)
			{
				continue;
			}

			if (!cells[indexOf["blocker"]].Equals("window", StringComparison.Ordinal)
				|| !cells[indexOf["route"]].Equals("compound", StringComparison.Ordinal)
				&& !cells[indexOf["route"]].Equals("other", StringComparison.Ordinal))
			{
				continue;
			}

			if (!int.TryParse(cells[indexOf["lineIndex"]], out var lineIndex))
			{
				continue;
			}

			wanted.Add((cells[indexOf["holdoutId"]], lineIndex));
		}

		return wanted;
	}

	private static string FoldName(string parsedName) =>
		string.Join(' ', parsedName.Split(' ', StringSplitOptions.RemoveEmptyEntries)
			.Select(t => IngredientLineResolver.SingularizeToken(t.ToLowerInvariant())));

	private static bool IsAllowedSet(string set) =>
		set.Equals("debug", StringComparison.Ordinal) || set.Equals("batch", StringComparison.Ordinal);

	private static string Clean(string value) => value.Replace('\t', ' ').Replace('\r', ' ').Replace('\n', ' ');
}
"}

{"path":"tools/LetUsCook.AutoWrongCensus/Services/AutoWrongCensusRunner.cs","i":"Rewriting runner with pair-based summary","content":"using System.Text.Json;
using System.Text.Json.Serialization;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>Runs one <c>census</c> or <c>pairs</c> invocation against a HoldoutGate trace.</summary>
public interface IAutoWrongCensusRunner
{
	/// <summary>Executes the invocation.</summary>
	/// <param name="cancellationToken">Shutdown token.</param>
	/// <returns>Process exit code: 0 success, 1 any refusal or missing input.</returns>
	Task<int> RunAsync(CancellationToken cancellationToken);
}

/// <summary>The two text sinks the runner writes to: TSV to stdout, summary/diagnostics to stderr.</summary>
/// <param name="Output">TSV sink.</param>
/// <param name="Error">Summary and error sink.</param>
public sealed record OutputWriters(TextWriter Output, TextWriter Error);

/// <summary>One classified line with its trace record (for the stderr diagnostics).</summary>
/// <param name="Record">The trace line.</param>
/// <param name="Classification">The relation and site.</param>
public sealed record ClassifiedLine(TraceLine Record, ClassificationResult Classification);

/// <summary>Default runner: classifies every <c>auto &amp;&amp; !correct</c> line of one trace.</summary>
public sealed class AutoWrongCensusRunner : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly IOptions<AutoWrongCensusOptions> _options;
	private readonly AutoWrongClassifier _classifier;
	private readonly FdcNormalizer _normalizer;
	private readonly OutputWriters _writers;

	/// <summary>Creates the runner.</summary>
	/// <param name="options">Bound CLI options.</param>
	/// <param name="classifier">The relation classifier.</param>
	/// <param name="normalizer">The production normalizer (for the <c>pairs</c> head folding).</param>
	/// <param name="writers">Output and error sinks.</param>
	public AutoWrongCensusRunner(
		IOptions<AutoWrongCensusOptions> options,
		AutoWrongClassifier classifier,
		FdcNormalizer normalizer,
		OutputWriters writers)
	{
		ArgumentNullException.ThrowIfNull(options);
		ArgumentNullException.ThrowIfNull(classifier);
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(writers);
		_options = options;
		_classifier = classifier;
		_normalizer = normalizer;
		_writers = writers;
	}

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		var options = _options.Value;
		switch (options.Command.ToLowerInvariant())
		{
			case CommandLineArgumentParser.CensusCommand:
				return await RunCensusAsync(options.TracePath, cancellationToken).ConfigureAwait(false);
			case CommandLineArgumentParser.PairsCommand:
				return await RunPairsAsync(options.CensusTsvPath, options.TracePath, cancellationToken).ConfigureAwait(false);
			default:
				await _writers.Error.WriteLineAsync("usage: AutoWrongCensus census <trace.jsonl> | AutoWrongCensus pairs <census.tsv> <trace.jsonl>").ConfigureAwait(false);
				return 1;
		}
	}

	private async Task<int> RunCensusAsync(string tracePath, CancellationToken cancellationToken)
	{
		var (records, refusal) = await LoadTraceAsync(tracePath, cancellationToken).ConfigureAwait(false);
		if (records is null)
		{
			await _writers.Error.WriteLineAsync(refusal).ConfigureAwait(false);
			return 1;
		}

		var classified = new List<ClassifiedLine>();
		foreach (var record in records)
		{
			if (!(record.Auto && !record.Correct))
			{
				continue;
			}

			var result = _classifier.Classify(record);
			if (result.Site.Length == 0)
			{
				await _writers.Error.WriteLineAsync(
					$"refused: line {record.HoldoutId}#{record.LineIndex} has atom path '{record.Atoms[0].Path}' — not ranker|override|curated.").ConfigureAwait(false);
				return 1;
			}

			classified.Add(new ClassifiedLine(record, result));
		}

		await _writers.Output.WriteLineAsync("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText").ConfigureAwait(false);
		foreach (var (record, row) in classified)
		{
			await _writers.Output.WriteLineAsync(TsvLine(
				row.HoldoutId, row.LineIndex, row.Set, row.Relation, row.Site, row.OverrideKey,
				row.AcceptedTier, row.KeyTier, row.AcceptedState, row.KeyState,
				row.ParsedName, row.KeyHead, row.AcceptedDesc, row.KeyDesc, row.RawText)).ConfigureAwait(false);
		}

		await WriteSummaryAsync(records.Count, classified, cancellationToken).ConfigureAwait(false);
		return 0;
	}

	private async Task WriteSummaryAsync(int traceLines, IReadOnlyList<ClassifiedLine> classified, CancellationToken cancellationToken)
	{
		var autoWrong = classified.Select(c => c.Classification).ToList();
		await _writers.Error.WriteLineAsync($"autoWrongCensus traced={traceLines} autoWrong={autoWrong.Count}").ConfigureAwait(false);

		await _writers.Error.WriteLineAsync("relation\tsite\tcount").ConfigureAwait(false);
		foreach (var byRelation in autoWrong.GroupBy(r => r.Relation, StringComparer.Ordinal).OrderBy(g => g.Key, StringComparer.Ordinal))
		{
			foreach (var cell in byRelation.GroupBy(r => r.Site, StringComparer.Ordinal).OrderBy(g => g.Key, StringComparer.Ordinal))
			{
				await _writers.Error.WriteLineAsync($"{byRelation.Key}\t{cell.Key}\t{cell.Count()}").ConfigureAwait(false);
			}
		}

		var otherCount = autoWrong.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		var otherPercent = autoWrong.Count > 0 ? otherCount * 100.0 / autoWrong.Count : 0.0;
		await _writers.Error.WriteLineAsync($"other={otherCount}/{autoWrong.Count} ({otherPercent:F1}%)").ConfigureAwait(false);

		foreach (var missing in autoWrong.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField!).OrderBy(g => g.Key, StringComparer.Ordinal))
		{
			await _writers.Error.WriteLineAsync($"missingField {missing.Key}={missing.Count()}").ConfigureAwait(false);
		}

		var overrideLines = autoWrong.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		await _writers.Error.WriteLineAsync(
			$"overrideKey yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")}").ConfigureAwait(false);

		var reuseLines = classified.Where(c => c.Classification.Site == AutoWrongClassifier.SiteReuse).ToList();
		var shouldReuseFalse = 0;
		foreach (var (record, _) in reuseLines)
		{
			var atom = record.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? record.Atoms[0];
			if (atom.LinkedIngredientId is not null
				&& !IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(atom.ParsedName), atom.LinkedIngredientId))
			{
				shouldReuseFalse++;
			}
		}

		await _writers.Error.WriteLineAsync($"reuse lines with ShouldReuse(parsedName, linkedIngredientId)=false: {shouldReuseFalse}/{reuseLines.Count}").ConfigureAwait(false);

		var tierRows = autoWrong.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier);
		var keyHigher = tierRows.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
		var acceptedHigher = tierRows.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier));
		await _writers.Error.WriteLineAsync($"row-choice-tier: key higher={keyHigher} accepted higher={acceptedHigher}").ConfigureAwait(false);

		foreach (var (_, row) in classified.Where(c => c.Classification.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			await _writers.Error.WriteLineAsync(
				$"qualifiers {row.HoldoutId}#{row.LineIndex} keyOnly=[{string.Join(' ', row.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(' ', row.AcceptedOnlyQualifiers ?? [])}]").ConfigureAwait(false);
		}
	}

	private async Task<int> RunPairsAsync(string censusTsvPath, string tracePath, CancellationToken cancellationToken)
	{
		if (!File.Exists(censusTsvPath))
		{
			await _writers.Error.WriteLineAsync($"refused: census TSV '{censusTsvPath}' not found.").ConfigureAwait(false);
			return 1;
		}

		var (records, refusal) = await LoadTraceAsync(tracePath, cancellationToken).ConfigureAwait(false);
		if (records is null)
		{
			await _writers.Error.WriteLineAsync(refusal).ConfigureAwait(false);
			return 1;
		}

		var traceByKey = records.ToDictionary(r => (r.HoldoutId, r.LineIndex));

		var censusLines = await File.ReadAllLinesAsync(censusTsvPath, cancellationToken).ConfigureAwait(false);
		if (censusLines.Length == 0)
		{
			await _writers.Error.WriteLineAsync($"refused: census TSV '{censusTsvPath}' is empty.").ConfigureAwait(false);
			return 1;
		}

		var header = censusLines[0].Split('\t');
		var idIndex = Array.IndexOf(header, "holdoutId");
		var lineIndexColumn = Array.IndexOf(header, "lineIndex");
		var blockerIndex = Array.IndexOf(header, "blocker");
		var routeIndex = Array.IndexOf(header, "route");
		if (idIndex < 0 || lineIndexColumn < 0 || blockerIndex < 0 || routeIndex < 0)
		{
			await _writers.Error.WriteLineAsync($"refused: census TSV '{censusTsvPath}' lacks one of holdoutId/lineIndex/blocker/route.").ConfigureAwait(false);
			return 1;
		}

		await _writers.Output.WriteLineAsync("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText").ConfigureAwait(false);
		var matched = 0;
		var unmatched = 0;
		foreach (var censusLine in censusLines.Skip(1))
		{
			var cells = censusLine.Split('\t');
			if (cells.Length <= Math.Max(routeIndex, lineIndexColumn))
			{
				continue;
			}

			if (cells[blockerIndex] != "window" || (cells[routeIndex] != "compound" && cells[routeIndex] != "other"))
			{
				continue;
			}

			if (!int.TryParse(cells[lineIndexColumn], out var lineIndex)
				|| !traceByKey.TryGetValue((cells[idIndex], lineIndex), out var traceRecord))
			{
				unmatched++;
				continue;
			}

			await _writers.Output.WriteLineAsync(TsvLine(
				traceRecord.HoldoutId,
				traceRecord.LineIndex,
				FoldHead(traceRecord.Atoms.Count > 0 ? traceRecord.Atoms[0].ParsedName : string.Empty),
				FoldKeyHead(traceRecord),
				traceRecord.RawText)).ConfigureAwait(false);
			matched++;
		}

		await _writers.Error.WriteLineAsync($"pairs emitted={matched} unmatchedCensusRows={unmatched}").ConfigureAwait(false);
		return 0;
	}

	private async Task<(IReadOnlyList<TraceLine>? Records, string Refusal)> LoadTraceAsync(string tracePath, CancellationToken cancellationToken)
	{
		if (!File.Exists(tracePath))
		{
			return (null, $"refused: trace '{tracePath}' not found.");
		}

		var records = new List<TraceLine>();
		var lineNumber = 0;
		foreach (var line in await File.ReadAllLinesAsync(tracePath, cancellationToken).ConfigureAwait(false))
		{
			lineNumber++;
			if (line.Length == 0)
			{
				continue;
			}

			var record = JsonSerializer.Deserialize<TraceLine>(line, JsonOptions)
				?? throw new InvalidOperationException($"trace line {lineNumber} deserialized to null");
			if (record.Set != "debug" && record.Set != "batch")
			{
				return (null, $"refused: set '{record.Set}' (D-029 allows debug|batch only) at line {lineNumber}.");
			}

			records.Add(record);
		}

		return (records, string.Empty);
	}

	private string FoldHead(string parsedName) =>
		string.Join(' ', _normalizer.NormalizeToTokens(parsedName).Select(IngredientLineResolver.SingularizeToken));

	private string FoldKeyHead(TraceLine record) =>
		record.ExpectedDescriptions.Count == 0
			? string.Empty
			: string.Join(' ', _classifier.KeyHeadPhrase(_normalizer.NormalizeToTokens(record.ExpectedDescriptions[0])));

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srlegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string TsvLine(params object[] cells) =>
		string.Join('\t', cells.Select(c => Sanitize(c?.ToString() ?? string.Empty)));

	private static string Sanitize(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');
}
"}

